// Monta a mensagem WhatsApp de acordo com o status do pedido
const body = $input.first().json.body || $input.first().json;
const nome = body.nome_cliente || 'Cliente';
const id8 = '#' + String(body.pedido_id || '').slice(-4).padStart(4, '0');
const tipo = body.tipo_entrega || 'retirada';
const total = parseFloat(body.total || 0).toFixed(2).replace('.', ',');

let mensagem = '';
if (body.status === 'pronto') {
  if (tipo === 'entrega') {
    mensagem = `✅ ${nome}, seu pedido ${id8} está *pronto* e saindo para entrega agora! 🛵\n\nAguarde pouquinho, já chega! 😊`;
  } else {
    mensagem = `✅ ${nome}, seu pedido ${id8} está *pronto para retirada!* 🫓\n\nPode vir buscar quando quiser! 😊`;
  }
} else if (body.status === 'saiu_entrega') {
  mensagem = `🛵 ${nome}, seu pedido ${id8} *saiu para entrega!*\n\nChegará em breve. Fique de olho! 😊`;
} else if (body.status === 'cancelado') {
  mensagem = `😔 ${nome}, infelizmente seu pedido ${id8} foi *cancelado*.\n\nEntre em contato conosco para mais informações. Pedimos desculpas pelo inconveniente.`;
}

if (!mensagem || !body.telefone) return [];

return [{ json: { telefone: body.telefone, mensagem } }];
